package com.example.miaumarket.data.local

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "session_prefs")

@Singleton
class SessionManager @Inject constructor(
    @ApplicationContext private val context: Context
) {
    private val TOKEN_KEY = stringPreferencesKey("jwt_token")

    val token: Flow<String?> = context.dataStore.data
        .map { preferences ->
            preferences[TOKEN_KEY]
        }

    suspend fun saveToken(token: String) {
        context.dataStore.edit { preferences ->
            preferences[TOKEN_KEY] = token
        }
    }

    suspend fun clearToken() {
        context.dataStore.edit { preferences ->
            preferences.remove(TOKEN_KEY)
        }
    }
}

package com.example.miaumarket.data.local

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "session_prefs")

@Singleton
class SessionManager @Inject constructor(
    @ApplicationContext private val context: Context
) : com.example.miaumarket.core.data.local.SessionManager {
    private val TOKEN_KEY = stringPreferencesKey("jwt_token")

    override val token: Flow<String?> = context.dataStore.data
        .map { preferences ->
            preferences[TOKEN_KEY]
        }

    override suspend fun saveToken(token: String) {
        context.dataStore.edit { preferences ->
            preferences[TOKEN_KEY] = token
        }
    }

    override suspend fun clearToken() {
        context.dataStore.edit { preferences ->
            preferences.remove(TOKEN_KEY)
        }
    }
}

package com.example.miaumarket.data.remote

import com.example.miaumarket.data.remote.dto.LoginRequest
import com.example.miaumarket.data.remote.dto.AuthResponse
import com.example.miaumarket.data.remote.dto.MeResponse
import com.example.miaumarket.data.remote.dto.RegisterRequest
import retrofit2.http.Body
import retrofit2.http.GET
import retrofit2.http.POST

interface AuthApi {
    @POST("api/auth/login")
    suspend fun login(@Body request: LoginRequest): AuthResponse

    @POST("api/auth/register")
    suspend fun register(@Body request: RegisterRequest): AuthResponse

    @GET("api/auth/me")
    suspend fun getMe(): MeResponse

    @POST("api/auth/logout")
    suspend fun logout()
}

package com.example.miaumarket.data.remote

// Re-export the canonical API from core-data so app code can keep existing imports
// while using the single source-of-truth implementations in the core-data module.
typealias AuthApi = com.example.miaumarket.core.data.remote.AuthApi

package com.example.miaumarket.data.remote

import com.example.miaumarket.data.remote.dto.ProductListResponse
import com.example.miaumarket.data.remote.dto.ProductResponse
import com.example.miaumarket.data.remote.dto.ProductRequest
import retrofit2.http.*

interface ProductApi {
    @GET("api/products")
    suspend fun getProducts(
        @Query("skip") skip: Int = 0,
        @Query("take") take: Int = 20,
        @Query("search") search: String? = null
    ): ProductListResponse

    @GET("api/products/{id}")
    suspend fun getProductById(@Path("id") id: Long): ProductResponse

    @POST("api/products")
    suspend fun createProduct(@Body product: ProductRequest): ProductResponse

    @PUT("api/products/{id}")
    suspend fun updateProduct(@Path("id") id: Long, @Body product: ProductRequest): ProductResponse

    @DELETE("api/products/{id}")
    suspend fun deleteProduct(@Path("id") id: Long)
}

package com.example.miaumarket.data.remote

// Re-export the canonical API from core-data so app code can keep existing imports
// while using the single source-of-truth implementations in the core-data module.
typealias ProductApi = com.example.miaumarket.core.data.remote.ProductApi

package com.example.miaumarket.data.remote.dto

import com.squareup.moshi.Json
import com.squareup.moshi.JsonClass

@JsonClass(generateAdapter = true)
data class LoginRequest(
    @Json(name = "email") val email: String,
    @Json(name = "password") val password: String
)

@JsonClass(generateAdapter = true)
data class AuthResponse(
    @Json(name = "token") val token: String,
    @Json(name = "user") val user: UserResponse
)

@JsonClass(generateAdapter = true)
data class RegisterRequest(
    @Json(name = "firstName") val firstName: String,
    @Json(name = "lastName") val lastName: String,
    @Json(name = "birthDate") val birthDate: String,
    @Json(name = "email") val email: String,
    @Json(name = "password") val password: String,
    @Json(name = "role") val role: String = "user"
)

@JsonClass(generateAdapter = true)
data class UserResponse(
    @Json(name = "id") val id: Long,
    @Json(name = "firstName") val firstName: String,
    @Json(name = "lastName") val lastName: String,
    @Json(name = "email") val email: String,
    @Json(name = "birthDate") val birthDate: String,
    @Json(name = "role") val role: String
)

@JsonClass(generateAdapter = true)
data class MeResponse(
    @Json(name = "user") val user: UserResponse
)

package com.example.miaumarket.data.remote.dto

import com.squareup.moshi.Json
import com.squareup.moshi.JsonClass

@JsonClass(generateAdapter = true)
data class ProductResponse(
    @Json(name = "id") val id: Long,
    @Json(name = "title") val name: String,
    @Json(name = "price") val price: Double? = null,
    @Json(name = "rawPrice") val rawPrice: String? = null,
    @Json(name = "image") val imageUrl: String? = null,
    @Json(name = "url") val sourceUrl: String? = null,
    @Json(name = "currency") val currency: String = "EUR",
    @Json(name = "source") val source: String? = null,
    @Json(name = "scrapedAt") val scrapedAt: String? = null,
    @Json(name = "createdAt") val createdAt: String? = null,
    @Json(name = "updatedAt") val updatedAt: String? = null
)

@JsonClass(generateAdapter = true)
data class ProductRequest(
    @Json(name = "title") val name: String,
    @Json(name = "price") val price: Double?,
    @Json(name = "image") val imageUrl: String?,
    @Json(name = "url") val sourceUrl: String?,
    @Json(name = "currency") val currency: String = "EUR",
    @Json(name = "source") val source: String = "manual"
)

@JsonClass(generateAdapter = true)
data class ProductListResponse(
    @Json(name = "total") val total: Int = 0,
    @Json(name = "take") val take: Int = 20,
    @Json(name = "skip") val skip: Int = 0,
    @Json(name = "sortBy") val sortBy: String? = null,
    @Json(name = "sortDir") val sortDir: String? = null,
    val items: List<ProductResponse>
)

package com.example.miaumarket.di

import com.example.miaumarket.data.remote.AuthApi
import com.example.miaumarket.data.remote.AuthInterceptor
import com.example.miaumarket.data.remote.ProductApi
import com.squareup.moshi.Moshi
import com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.moshi.MoshiConverterFactory
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {

    // Set to http://10.0.2.2:3000/ to reach the host machine's loopback interface from an Android emulator.
    private const val BASE_URL = "http://10.0.2.2:3000/"

    @Provides
    @Singleton
    fun provideMoshi(): Moshi {
        return Moshi.Builder()
            .add(KotlinJsonAdapterFactory())
            .build()
    }

    @Provides
    @Singleton
    fun provideLoggingInterceptor(): HttpLoggingInterceptor {
        return HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }
    }

    @Provides
    @Singleton
    fun provideOkHttpClient(
        loggingInterceptor: HttpLoggingInterceptor,
        authInterceptor: AuthInterceptor
    ): OkHttpClient {
        return OkHttpClient.Builder()
            .addInterceptor(loggingInterceptor)
            .addInterceptor(authInterceptor)
            .build()
    }

    @Provides
    @Singleton
    fun provideRetrofit(okHttpClient: OkHttpClient, moshi: Moshi): Retrofit {
        return Retrofit.Builder()
            .baseUrl(BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(MoshiConverterFactory.create(moshi))
            .build()
    }

    @Provides
    @Singleton
    fun provideAuthApi(retrofit: Retrofit): AuthApi {
        return retrofit.create(AuthApi::class.java)
    }

    @Provides
    @Singleton
    fun provideProductApi(retrofit: Retrofit): ProductApi {
        return retrofit.create(ProductApi::class.java)
    }
}

package com.example.miaumarket.di

import com.example.miaumarket.data.remote.AuthInterceptor
import com.example.miaumarket.data.local.SessionManager
import com.example.miaumarket.core.data.local.SessionManager as CoreSessionManager
import com.example.miaumarket.core.data.remote.AuthApi
import com.example.miaumarket.core.data.remote.ProductApi
import com.squareup.moshi.Moshi
import com.squareup.moshi.kotlin.reflect.KotlinJsonAdapterFactory
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.moshi.MoshiConverterFactory
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {

	// Same default used by core-data (emulator -> host)
	private const val BASE_URL = "http://10.0.2.2:3000/"

	@Provides
	@Singleton
	fun provideMoshi(): Moshi {
		return Moshi.Builder()
			.add(KotlinJsonAdapterFactory())
			.build()
	}

	@Provides
	@Singleton
	fun provideLoggingInterceptor(): HttpLoggingInterceptor {
		return HttpLoggingInterceptor().apply {
			level = HttpLoggingInterceptor.Level.BODY
		}
	}

	@Provides
	@Singleton
	fun provideOkHttpClient(
		loggingInterceptor: HttpLoggingInterceptor,
		authInterceptor: AuthInterceptor
	): OkHttpClient {
		return OkHttpClient.Builder()
			.addInterceptor(loggingInterceptor)
			.addInterceptor(authInterceptor)
			.build()
	}

	@Provides
	@Singleton
	fun provideRetrofit(okHttpClient: OkHttpClient, moshi: Moshi): Retrofit {
		return Retrofit.Builder()
			.baseUrl(BASE_URL)
			.client(okHttpClient)
			.addConverterFactory(MoshiConverterFactory.create(moshi))
			.build()
	}

	@Provides
	@Singleton
	fun provideAuthApi(retrofit: Retrofit): AuthApi {
		return retrofit.create(AuthApi::class.java)
	}

	@Provides
	@Singleton
	fun provideProductApi(retrofit: Retrofit): ProductApi {
		return retrofit.create(ProductApi::class.java)
	}

	// Bind app's Android SessionManager to the core-data SessionManager interface
	@Provides
	@Singleton
	fun provideCoreSessionManager(sessionManager: SessionManager): CoreSessionManager {
		return sessionManager
	}
}

