/**
 * AuthInterceptor depends only on the `SessionManager` interface defined in
 * core-data. The actual Android implementation will be provided by the app
 * module and injected via Hilt there. Keep this class platform-neutral.
 */
class AuthInterceptor(
    private val sessionManager: SessionManager
) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val token = runBlocking {
            sessionManager.token.first()
        }
        val request = chain.request().newBuilder().apply {
            token?.let {
                addHeader("Authorization", "Bearer $it")
            }
        }.build()
        return chain.proceed(request)
    }
}

package com.example.miaumarket.core.data.remote

import com.example.miaumarket.core.data.remote.dto.ProductListResponse
import com.example.miaumarket.core.data.remote.dto.ProductResponse
import com.example.miaumarket.core.data.remote.dto.ProductRequest
import retrofit2.http.*

interface ProductApi {
    @GET("api/products")
    suspend fun getProducts(
        @Query("skip") skip: Int = 0,
        @Query("take") take: Int = 20,
        @Query("search") search: String? = null
    ): ProductListResponse

    @GET("api/products/{id}")
    suspend fun getProductById(@Path("id") id: Long): ProductResponse

    @POST("api/products")
    suspend fun createProduct(@Body product: ProductRequest): ProductResponse

    @PUT("api/products/{id}")
    suspend fun updateProduct(@Path("id") id: Long, @Body product: ProductRequest): ProductResponse

    @DELETE("api/products/{id}")
    suspend fun deleteProduct(@Path("id") id: Long)
}

