package com.example.miaumarket.wear

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.runtime.remember
import androidx.wear.compose.navigation.rememberSwipeDismissableNavController
import com.example.miaumarket.wear.ui.navigation.WearNavGraph
import com.example.miaumarket.wear.ui.theme.MiauMarketWearTheme
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MiauMarketWearTheme {
                val navController = rememberSwipeDismissableNavController()
                WearNavGraph(navController = navController)
            }
        }
    }
}

package com.example.miaumarket.wear

import android.app.Application
import dagger.hilt.android.HiltAndroidApp

@HiltAndroidApp
class WearApplication : Application()

package com.example.miaumarket.wear.ui.navigation

import androidx.compose.runtime.Composable
import androidx.navigation.NavHostController
import androidx.wear.compose.navigation.SwipeDismissableNavHost
import androidx.wear.compose.navigation.composable
import com.example.miaumarket.wear.ui.screens.catalog.CatalogScreen
import com.example.miaumarket.wear.ui.screens.product.ProductDetailScreen

sealed class WearRoute(val route: String) {
    object Catalog : WearRoute("catalog")
    object ProductDetail : WearRoute("product/{productId}") {
        fun createRoute(productId: Long) = "product/$productId"
    }
}

@Composable
fun WearNavGraph(navController: NavHostController) {
    SwipeDismissableNavHost(
        navController = navController,
        startDestination = WearRoute.Catalog.route
    ) {
        composable(WearRoute.Catalog.route) {
            CatalogScreen(
                onProductClick = { productId ->
                    navController.navigate(WearRoute.ProductDetail.createRoute(productId))
                }
            )
        }

        composable(WearRoute.ProductDetail.route) {
            ProductDetailScreen(
                onBackClick = {
                    navController.popBackStack()
                }
            )
        }
    }
}

package com.example.miaumarket.wear.ui.screens.catalog

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.wear.compose.material.Text
import androidx.wear.compose.material.Chip

@Composable
fun CatalogScreen(
    onProductClick: (Long) -> Unit,
    viewModel: CatalogViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF1A1A1A))
    ) {
        when {
            uiState.isLoading && uiState.products.isEmpty() -> {
                LoadingScreen()
            }
            uiState.error != null && uiState.products.isEmpty() -> {
                val errorMsg = uiState.error
                ErrorScreen(
                    error = errorMsg,
                    onRetry = { viewModel.retry() }
                )
            }
            uiState.products.isEmpty() -> {
                EmptyScreen()
            }
            else -> {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(vertical = 4.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    items(uiState.products) { product ->
                        ProductCard(
                            product = product,
                            onClick = { onProductClick(product.id) }
                        )
                    }

                    if (uiState.canLoadMore && !uiState.isLoading) {
                        item {
                            Chip(
                                onClick = { viewModel.loadNextPage() },
                                modifier = Modifier.fillMaxWidth(0.9f),
                                label = { Text("Cargar más", fontSize = 10.sp) }
                            )
                        }
                    }

                    if (uiState.isLoading) {
                        item {
                            LoadingIndicator()
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ProductCard(
    product: com.example.miaumarket.core.data.remote.dto.ProductResponse,
    onClick: () -> Unit
) {
    Chip(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(0.95f),
        label = {
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Text(
                    text = product.name,
                    fontSize = 11.sp,
                    maxLines = 1,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth()
                )
                if (product.price != null) {
                    Text(
                        text = "€${String.format("%.2f", product.price)}",
                        fontSize = 9.sp,
                        color = Color(0xFFFF6B6B)
                    )
                }
            }
        }
    )
}

@Composable
fun LoadingScreen() {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        LoadingIndicator()
    }
}

@Composable
fun LoadingIndicator() {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Text("Cargando...", fontSize = 12.sp)
    }
}

@Composable
fun ErrorScreen(
    error: String?,
    onRetry: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = error ?: "Error desconocido",
                fontSize = 10.sp,
                textAlign = TextAlign.Center
            )
            Chip(
                onClick = onRetry,
                modifier = Modifier.fillMaxWidth(0.9f),
                label = { Text("Reintentar", fontSize = 10.sp) }
            )
        }
    }
}

@Composable
fun EmptyScreen() {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = "No hay productos",
            fontSize = 11.sp,
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(16.dp)
        )
    }
}

package com.example.miaumarket.wear.ui.screens.catalog

import androidx.compose.runtime.State
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.miaumarket.core.data.domain.repository.ProductRepository
import com.example.miaumarket.core.data.remote.dto.ProductResponse
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.launch
import javax.inject.Inject

data class CatalogUiState(
    val products: List<ProductResponse> = emptyList(),
    val isLoading: Boolean = false,
    val error: String? = null,
    val currentPage: Int = 1,
    val canLoadMore: Boolean = true
)

@HiltViewModel
class CatalogViewModel @Inject constructor(
    private val productRepository: ProductRepository
) : ViewModel() {

    private val _uiState = mutableStateOf(CatalogUiState())
    val uiState: State<CatalogUiState> = _uiState

    init {
        loadProducts()
    }

    private fun loadProducts() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)
            val page = _uiState.value.currentPage
            val size = 10 // Reduced for watch screen

            val result = productRepository.getProducts(page, size, null)

            result.onSuccess { response ->
                val newProducts = if (page == 1) {
                    response.items
                } else {
                    _uiState.value.products + response.items
                }

                val hasMoreItems = (page - 1) * size + response.items.size < response.total

                _uiState.value = _uiState.value.copy(
                    products = newProducts,
                    isLoading = false,
                    canLoadMore = hasMoreItems
                )
            }

            result.onFailure { exception ->
                _uiState.value = _uiState.value.copy(
                    isLoading = false,
                    error = exception.message ?: "Error desconocido"
                )
            }
        }
    }

    fun loadNextPage() {
        if (!_uiState.value.isLoading && _uiState.value.canLoadMore) {
            _uiState.value = _uiState.value.copy(currentPage = _uiState.value.currentPage + 1)
            loadProducts()
        }
    }

    fun retry() {
        _uiState.value = _uiState.value.copy(currentPage = 1)
        loadProducts()
    }
}

package com.example.miaumarket.wear.ui.screens.product

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
