import androidx.compose.foundation.verticalScroll
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.wear.compose.material.Chip
import androidx.wear.compose.material.Text

@Composable
fun ProductDetailScreen(
    onBackClick: () -> Unit,
    viewModel: ProductDetailViewModel = hiltViewModel()
) {
    val uiState = viewModel.uiState.collectAsState()

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF1A1A1A))
    ) {
        when {
            uiState.value.isLoading -> {
                LoadingState()
            }
            uiState.value.error != null -> {
                val errorMsg = uiState.value.error
                ErrorState(
                    error = errorMsg,
                    onRetry = { viewModel.retry() },
                    onBack = onBackClick
                )
            }
            uiState.value.product != null -> {
                ProductContent(
                    product = uiState.value.product!!,
                    isAddedToCart = uiState.value.isAddedToCart,
                    onAddToCart = { viewModel.addToCart() },
                    onBack = onBackClick
                )
            }
        }
    }
}

@Composable
fun ProductContent(
    product: com.example.miaumarket.core.data.remote.dto.ProductResponse,
    isAddedToCart: Boolean,
    onAddToCart: () -> Unit,
    onBack: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 8.dp, vertical = 8.dp),
        verticalArrangement = Arrangement.SpaceBetween,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(4.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = product.name,
                fontSize = 12.sp,
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth(),
                maxLines = 2
            )

            if (product.price != null) {
                Text(
                    text = "€${String.format("%.2f", product.price)}",
                    fontSize = 11.sp,
                    color = Color(0xFFFF6B6B)
                )
            }

            if (!product.sourceUrl.isNullOrEmpty()) {
                Text(
                    text = "Origen: ${product.source ?: "Desc."}",
                    fontSize = 9.sp,
                    color = Color.Gray,
                    maxLines = 1
                )
            }
        }

        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(4.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Chip(
                onClick = onAddToCart,
                modifier = Modifier.fillMaxWidth(0.9f),
                label = { Text(if (isAddedToCart) "✓ Añad." else "Añadir", fontSize = 10.sp) }
            )

            Chip(
                onClick = onBack,
                modifier = Modifier.fillMaxWidth(0.9f),
                label = { Text("Atrás", fontSize = 10.sp) }
            )
        }
    }
}

@Composable
fun LoadingState() {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        Text("Cargando...", fontSize = 12.sp)
    }
}

@Composable
fun ErrorState(
    error: String?,
    onRetry: () -> Unit,
    onBack: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = error ?: "Error desconocido",
                fontSize = 10.sp,
                textAlign = TextAlign.Center
            )
            Chip(onClick = onRetry, label = { Text("Reintentar", fontSize = 10.sp) }, modifier = Modifier.fillMaxWidth(0.9f))
            Chip(onClick = onBack, label = { Text("Atrás", fontSize = 10.sp) }, modifier = Modifier.fillMaxWidth(0.9f))
        }
    }
}

